create table s(a text, b blob, n);
insert into s values('héllo wörld', x'00ff41', 12.5), ('日本語テキスト', x'', -7), ('', NULL, 0), ('a''b"c', x'616263', 1e300);
select a, octet_length(a), length(a), octet_length(b), length(b), octet_length(n), length(n) from s;
select substr(a, 2, 3), substr(a, -2), substr(b, 2), instr(a, 'l'), instr(a, '本'), replace(a, 'ö', 'oe'), quote(a), quote(b) from s;
select upper(a), lower(a), trim(a, 'hé'), ltrim(a, 'h'), rtrim(a, 'd'), hex(a), hex(b), unicode(a), char(104, 233, 26085) from s;
select a like '%ö%', a glob '*l*', a like 'H%', printf('%s|%5.2f|%d|%q', a, n, length(a), a), format('%10s', a) from s;
select concat(a, n, b), concat_ws('-', a, n), group_concat(a, '|'), string_agg(a, ','), min(a), max(a), count(distinct a) from s;
select cast(a as blob), cast(b as text), cast(n as text), typeof(cast(n as text)), a || n, n || a from s;
select a, a < 'b', a = 'héllo wörld', a collate nocase > 'H' from s order by a;
select unhex('48c3a9'), cast(unhex('48c3a9') as text), zeroblob(3) || 'x', length(zeroblob(5) || 'ab'), randomblob(0) is not null;
select sqlite_version() is not null, typeof(soundex('hello')), coalesce(NULL, a), nullif(a, ''), iif(a = '', 'empty', a) from s;
select json_object('k', a), json_array(a, n), json_extract(json_object('k', a), '$.k'), a -> '$' from s where a <> '';
select date('2013-10-07'), datetime(1092941466, 'unixepoch'), strftime('%Y-%m', '2013-10-07'), timediff('2023-02-15', '2023-01-01');
select abs(n), round(n, 1), typeof(n), n + 1, n * 2, sum(n) over (), total(n) over () from s;
select a from s where a in ('', 'héllo wörld') order by a desc;
create index si on s(a);
select a from s where a > 'h' order by a;
select a from s where a between '' and 'z' order by a;
pragma integrity_check;
